import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;class Solution{interface Worker{String run(String value)throws Exception;}record Result(List<String>values,int retries){}static Result process(List<String>items,Worker worker)throws Exception{ExecutorService pool=Executors.newFixedThreadPool(2);AtomicInteger retries=new AtomicInteger();try{List<Future<String>>futures=new ArrayList<>();for(String item:items)futures.add(pool.submit(()->{for(int attempt=1;;attempt++){try{return worker.run(item);}catch(Exception error){if(attempt>=3)throw error;retries.incrementAndGet();}}}));List<String>values=new ArrayList<>();for(Future<String>future:futures)values.add(future.get());return new Result(List.copyOf(values),retries.get());}finally{pool.shutdownNow();}}}
